<script setup lang="ts">import {ref,computed,watch} from 'vue';import {useRoute} from 'vue-router';import {useResearchData} from '../hooks/useResearch';import {useAuth} from '../stores/auth';import {useAction} from '../hooks/useAction';import {annotateSample} from '../api/samples';import StudySelector from '../components/StudySelector.vue';import CompositionMatrix from '../components/CompositionMatrix.vue';import DataTable from '../components/common/DataTable.vue';import Notice from '../components/common/Notice.vue';const s=useResearchData(),auth=useAuth(),a=useAction(),route=useRoute(),id=ref(Number(route.query.study)||0),selected=ref(0),note=ref('');const study=computed(()=>s.studies.find(x=>x.id===id.value)||s.studies[0]),sample=computed(()=>s.samples.find(x=>x.id===selected.value)||s.samples[0]);watch(()=>study.value?.id,async value=>{if(value)await s.loadStudy(value)},{immediate:true});watch(()=>sample.value,()=>note.value=sample.value?.note||'');function save(){a.execute(async()=>{await annotateSample(sample.value.id,note.value);await s.loadStudy(study.value.id)})}</script><template><div class="page"><div class="page-title"><div><p class="eyebrow">PHASE SOURCES / 02</p><h1>相份额来源<span>原相对量、组规模与零值口径一起核对。</span></h1></div></div><Notice :message="s.error||a.error.value" @retry="s.refresh"/><StudySelector :studies="s.studies" :model-value="study?.id||0" @update:model-value="id=$event"/><div v-if="study" :class="['source-note',!study.supported?'warning':'']"><b>{{study.reason}}</b><p>{{study.description}}</p><small>{{study.source}} · {{Object.entries(study.group_counts).map(([g,n])=>g+' '+n).join(' / ')}}</small></div><div class="section-heading"><h2>固定相通道</h2><span>互斥分析相 / 不解释绝对产量</span></div><DataTable :head="['次序','相通道','单位','口径']"><tr v-for="c in s.components" :key="c.id"><td>{{c.position+1}}</td><td>{{c.label}}</td><td>{{c.unit}}</td><td>{{c.meaning}}</td></tr></DataTable><div class="source-grid"><section><div class="section-heading"><h2>原始样本矩阵</h2><span>{{s.samples.length}}样本 / 点击一行批注</span></div><CompositionMatrix :components="s.components" :samples="s.samples" :selected="sample?.id" @select="selected=$event"/></section><aside class="sample-reading"><span class="eyebrow">SELECTED SAMPLE</span><h2>{{sample?.code}}</h2><p>{{sample?.group}} / {{sample?.zero_count}}个零<br/>零按未检出通道处理，不静默加伪计数。</p><label>样本批注<textarea aria-label="样本批注" v-model="note" :disabled="auth.user?.role==='viewer'"/></label><button v-if="auth.user?.role!=='viewer'" class="outline" :disabled="a.busy.value||note.length<8||!sample" @click="save">保存批注</button><small>数值与分组只读；后续运行冻结批注，历史运行不回写。</small></aside></div></div></template>
